  "guide.cloud.parametersOnALog": "Parámetros en escala logarítmica: cada línea es 10× la anterior. OpenAI no publica el tamaño de su modelo más avanzado de ChatGPT, así que esa barra es un cálculo externo y se muestra difuminada. *Una regla general, no un límite fijo.",
