  "channels.chooseWhereYouWant": "选择你想在哪里和 sudo 聊天。",
  "set.channels.comingSoon": "即将推出",
  "set.channels.wantToGiveYour": "<strong>想给助手一个自己的手机号？</strong>我们用的是第三方运营商 Tello：<a href=\"https://www.amazon.com/dp/B08H5SM9M9\">购买 Tello SIM 卡</a>。有了第二个号码，就能为助手单独注册一个 WhatsApp 账号，它会用自己的联系人身份给你发消息，而不是在你自己的对话里。<small>不是广告，只是我们自己在用。任何能接收短信的号码都可以，建议你多比较，选适合自己的。</small>",
  "set.channels.close": "关闭",
  "set.channels.settingsTitle": "WhatsApp 设置",
  "set.channels.whatsappOptions": "WhatsApp 选项",
  "set.channels.offByDefaultRead": "默认关闭。只读：它能看到你在自己关联的 WhatsApp 上和别人的聊天，但从不回复他们。",
  "set.channels.whatItAllowsYour": "<strong>它能做什么。</strong>助手可以读取<em>你自己</em>关联的 WhatsApp 里的聊天，也就是你和别人的对话，这样它能提醒你事情，也能注意到谁在等你回复。<br><br><strong>它绝不会做什么。</strong>它绝不会在这些聊天里回复任何人，也不会给他们发消息。它只和你说话。<br><br><strong>只限你自己的账号。</strong>这只适用于关联为“你的 WhatsApp”的账号。助手自己的号码没有别的聊天可读。<br><br><strong>默认关闭。</strong>在你打开之前什么都不会读取。关闭后立即停止。",
  "set.channels.offByDefaultYour": "默认关闭。每日摘要和提醒里也会列出可能还在等你回复的人。需要先打开上面那一项。",
  "conn.letSudoUseYour": "让 sudo 真正使用你的其他应用（发邮件、加日程、提交问题），而不只是聊聊它们。",
  "set.connectors.connectorsLetSudoUse": "连接器让 sudo 真正使用你的其他应用（发邮件、加日程、提交问题），而不只是聊聊它们。",
  "set.connectors.composioApiKey": "Composio API 密钥",
  "set.connectors.pasteYourKey": "粘贴你的密钥",
  "set.connectors.fromDashboardComposioDev": "在 <strong>dashboard.composio.dev</strong> → Connect → Settings → Sessions &amp; API Key 获取。以 <code>ck_</code> 开头。只保存在这台设备上，保存后连接器即开启。",
  "set.connectors.saveKey": "保存密钥",
  "set.connectors.removeKey": "删除密钥",
  "set.connectors.whatYouCanConnect": "可以连接什么",
  "set.connectors.1600AppsYour": "助手可用的 1600 多个应用",
  "set.connectors.andMuchMoreTo": "…还有更多。想连接哪个，直接跟助手说，它会发给你登录链接。<a href=\"https://composio.dev/toolkits\">查看全部应用</a>",
  "set.connectors.whatIsComposioWhy": "Composio 是什么？我们为什么用它，以及你的隐私 ⓘ",
  "set.connectors.whyWeUseIt": "<strong>为什么用它。</strong>把助手一个个连到你的应用上，意味着每个连接都得自己做，而且应用一更新就容易坏。Composio 为 1600 多个应用维护着现成的连接，你登录一次，sudo 就能使用。<br><br><strong>你的登录信息。</strong>你在每个应用自己的页面上登录，所以 sudo 永远看不到你的密码。Composio 会加密保存你授予的权限，只在 sudo 要做某件事的那一刻使用，从不交给 sudo 或 AI 模型。你随时可以在 Composio 控制台断开任何应用。<br><br><strong>隐私。</strong>Composio 表示不会出售或分享你 Google 账户的数据，也不会用你的数据训练 AI。它通过了独立审计（SOC 2 Type II、ISO 27001）。默认会保留 sudo 在各应用中操作的日志，最长一年；可以通过设置关闭（Zero Data Retention），也可以发邮件到 support@composio.dev 要求删除你的数据。<a href=\"https://composio.dev/privacy\">隐私政策</a> · <a href=\"https://trust.composio.dev\">安全</a>",
  "set.connectors.otherWaysToExtend": "扩展 sudo 的其他方式",
  "set.connectors.mcpServers": "MCP 服务器 ⓘ",
  "set.connectors.mcpIsAnOpen": "<strong>MCP</strong> 是一个开放标准，用来给助手增加新能力。MCP 服务器是一个提供工具的小程序（读取某个数据库、搜索某些文档、控制某个应用），sudo 可以调用这些工具。<br><br>Composio 是免设置的选择；当你想要特定的或自己托管的功能时，就用 MCP。它在你的设备上运行，数据不会离开你的网络。<br><br><em>还没接通</em>：它和运行命令一样需要谨慎，因为 MCP 服务器是你选择信任的代码。",
  "set.connectors.cliTools": "命令行工具 ⓘ",
  "set.connectors.commandLineProgramsAlready": "设备上已有的命令行程序：<code>git</code>、<code>curl</code>、<code>ffmpeg</code>，以及你安装的其他程序。这是能力最广、防护最少的选项。<br><br>在 <strong>sudo 能做什么 → 在这台设备上运行命令</strong> 中开启。请先读那里的警告：网页里可能藏着专门诱骗助手执行有害操作的文字。",
  "settings.backToSettings": "返回设置",
