  "set.access.thisNetworkAsksFor": "这个网络需要",
  "set.access.username2": "用户名",
  "set.access.joinNetwork": "加入网络",
  "set.access.pickANetworkAbove": "在上面选一个网络，输入密码后加入。如果你是在家庭网络上打开的控制面板，sudo 切换网络时页面会断开几秒钟，之后会在新地址恢复。",
  "set.access.aboutAccessFromAnywhere": "关于随时随地访问",
  "set.access.normallyYourDashboardOnly": "平时控制面板只能在家里的 Wi‑Fi 上用。打开这项后，sudo 会创建一个公开网址，在任何地方都能访问你的设备，出门在外很方便。<br><br><strong>请像对待密码一样对待这个链接。</strong>没有登录界面：拿到链接的人都能和你的助手聊天、修改这些设置。不要公开发布，也不要发给你不放心把解锁手机交给的人。<br><br>设备重启后链接会变。不需要时请关掉。",
  "set.access.copy": "复制",
  "set.access.passwordForThePublic": "公开链接的密码",
  "set.access.askForAPassword": "要求输入密码",
  "set.access.appliesToThePublic": "只对公开链接生效。家庭网络从不需要密码。",
  "set.access.requireAPasswordOn": "公开链接需要密码",
  "set.access.changeIt": "修改密码",
  "set.access.atLeast10Characters": "至少 10 个字符",
  "set.access.savePassword": "保存密码",
  "set.access.stronglyRecommendedLeaveThis": "<strong>强烈建议保持开启。</strong>关闭后，公开链接就是一个任何人拿到都能打开你控制面板的网址：不用登录、不限次数、在世界任何地方都行。他们可以读你的聊天、改你的设置、用你的 API 额度。链接会被分享、被你粘贴过的服务记录下来，也会被误转发。",
  "set.access.localDashboardHttpRaspberrypi": "本地控制面板：<strong>http://raspberrypi.local</strong>",
  "set.access.wiFiRegion": "Wi‑Fi 地区",
  "set.access.autoDetectedAtSetup": "设置时自动检测。决定设备可以使用哪些 Wi‑Fi 信道。只有把设备带到其他国家时才需要修改。",
  "set.ssh.developerAccess": "开发者访问",
  "set.ssh.terminalAccessSsh": "终端访问（SSH）",
  "set.ssh.logIntoThisDevice": "从你的电脑登录这台设备，直接在上面操作。",
  "set.ssh.toggleTerminalAccess": "开关终端访问",
  "set.ssh.aboutTerminalAccess": "关于终端访问",
  "set.ssh.itSYourDevice": "这是你的设备，你可以拥有完全的访问权。打开后，你可以从家里 Wi‑Fi 上的电脑登录，像用其他电脑一样使用它：安装软件、读取文件、修改 sudo 的工作方式。<br><br><strong>日常使用不需要这个。</strong>设备该做的事，都能在这个控制面板里完成。<br><br><strong>只限家里的 Wi‑Fi。</strong>即使打开了<em>随时随地访问</em>，也永远无法从互联网访问到它。<br><br>如果设备被重新烧录，你手动做的修改都会还原。",
  "set.ssh.aboutThisPassword": "关于这个密码",
  "set.ssh.generatedJustNowFor": "刚刚为设备的用户账户生成。请复制保存到安全的地方；只要在家里的 Wi‑Fi 上，随时可以回到这里再看。",
  "set.ssh.openThisPageOn": "在家里的 Wi‑Fi 上打开这个页面才能看到密码，公开链接上不会显示。",
  "set.ssh.preferToUseYour": "想用你自己的 SSH 密钥？",
  "set.ssh.aboutSshKeys": "关于 SSH 密钥",
  "set.ssh.anSshKeyIs": "SSH 密钥是你电脑上的一对文件：私钥永远不离开你的电脑，公钥可以放心分享。你把公钥放在这里，电脑连接时会证明它持有私钥。不用输入或记住密码。<br><br><strong>如果你还没有</strong>，跳过这一步就行，上面的密码完全够用。要创建一个，在电脑上运行 <code>ssh-keygen -t ed25519</code>，然后粘贴 <code>~/.ssh/id_ed25519.pub</code> 的内容。",
  "set.ssh.useThisKeyInstead": "改用这个密钥",
  "set.ssh.aboutClaudeCode": "关于 Claude Code",
  "set.ssh.claudeCodeIsAn": "Claude Code 是一个在终端里运行的 AI 助手，可以读取和修改这台设备上的文件，想定制 sudo 的工作方式时很方便。<br><br>我们没有预装它，这样设备更小巧，你也总能用上最新版本。安装需要几分钟，并且要联网。可以在这里直接查看进度。",
  "set.ssh.installClaudeCode": "安装 Claude Code",
  "set.ssh.installedOpenATerminal": "已安装。在电脑上打开终端，运行这些命令：",
  "set.ssh.openaiSTerminalAssistant": "OpenAI 的终端助手。思路一样，服务商不同，两个可以都装。",
  "set.ssh.installCodex": "安装 Codex",
  "set.github.giveSudoAGithub": "给 sudo 一个 GitHub 令牌，它就能直接处理你的代码仓库（克隆、推送修改、提交 issue），而不只是一步步指导你。",
  "set.github.githubUsername": "GitHub 用户名",
  "set.github.optional": "可选",
  "set.github.yourHandle": "你的用户名",
  "set.github.personalAccessToken": "个人访问令牌",
  "set.github.ghpOrGithubPat": "ghp_… 或 github_pat_…",
  "set.github.createOneAtGithub": "在 <strong>github.com → Settings → Developer settings → Personal access tokens</strong> 创建。只勾选 sudo 需要的权限；最安全的是只限于你关心的仓库的细粒度令牌。只保存在这台设备上。",
  "set.github.saveToken": "保存令牌",
  "set.github.letSudoUseMy": "允许 sudo 使用我的仓库",
  "set.github.whenOffTheToken": "关闭时，令牌仍然保存着，但 sudo 无法访问 GitHub。",
  "set.github.whatTheTokenCan": "令牌能做什么 ⓘ",
  "set.github.aTokenIsA": "令牌是打开你 GitHub 账户的一把钥匙。它能访问的范围，正是你创建时勾选的权限：仓库权限让 sudo 能克隆、推送和提交 issue，别的都不行。<br><br><strong>请像对待密码一样对待它。</strong>除非你想让 sudo 在你的仓库里工作，否则保持关闭；用完立刻在 GitHub 上撤销。它只保存在这台设备上，除了和 GitHub 通信，从不离开设备。",
  "settings.billingCredits": "付费与额度",
  "set.billing.billingCredits": "付费与额度",
  "set.billing.donTWantTo": "<strong>不想折腾 API 密钥？</strong>在这里充值，路由交给我们处理：不用注册账户，不用粘贴密钥，也不用分别盯着各家的账单。",
  "set.billing.usdCreditsAvailable": "可用额度（美元）",
