  "set.providers.openrouterOpenaiAnthropicGemini": "OpenRouter أو OpenAI أو Anthropic أو Gemini أو Venice أو DeepSeek، دون الحاجة إلى ذكر أيّها.",
  "set.providers.orChooseTheProvider": "أو اختر المزوّد بنفسك",
  "set.providers.whichOneShouldI": "أيّها أضيف؟ ⓘ",
  "set.providers.youDonTNeed": "<strong>لا تحتاج إلى أيٍّ منها.</strong> رصيد Sudo يغطي كل شيء من البداية.<br><br><strong>OpenRouter</strong> هو ما تضيفه إن كنت ستضيف واحدًا فقط: مفتاح واحد يصل إلى معظم النماذج من كل المزوّدين.<br><br>المفتاح المباشر (OpenAI وAnthropic وGemini) أرخص عادةً لكل رسالة مع نماذج ذلك المزوّد، ويستحق ذلك إن كنت تدفع لهم أصلًا.<br><br>لا تغادر المفاتيح الجهاز إلا إلى المزوّد الذي تخصّه. لحذف مفتاح، أفرغ المربع واحفظ.",
  "settings.security": "الأمان",
  "set.abilities.whatSudoCanDo": "ما يستطيع sudo فعله",
  "set.abilities.abilitiesYouCanGrant": "قدرات يمكنك منحها لمساعدك. كل شيء هنا بقرارك، فشغّل ما تحتاجه حين تحتاجه.",
  "set.abilities.searchTheWeb": "البحث في الويب",
