  "set.abilities.runCommandsOnThis": "تشغيل الأوامر على هذا الجهاز",
  "set.abilities.onByDefaultThe": "يعمل افتراضيًا. يستطيع المساعد استخدام الطرفية: تثبيت البرامج، وتعديل الملفات، وفحص النظام. أوقفه ليكتفي بالحديث.",
  "set.abilities.toggleCommandAccess": "تشغيل الأوامر أو إيقافها",
  "set.abilities.aboutCommandAccess": "عن صلاحية تشغيل الأوامر",
  "set.abilities.whyItSOn": "<strong>لماذا يعمل.</strong> الفكرة كلها أن ينجز الأمور. بالطرفية يستطيع المساعد فعلًا أن يثبّت ويصلح ويفحص الأشياء على Pi بدلًا من أن يصف لك ما يمكنك فعله بنفسك.<br><br><strong>ما الذي تقبله.</strong> لديه على هذا الجهاز الصلاحيات نفسها التي لديك حين تسجّل الدخول. وهو يقرأ صفحات الويب أيضًا، وقد تحتوي صفحة على نص مكتوب لخداعه ودفعه إلى تشغيل شيء ما، فهو لا يميّز دائمًا بين التعليمات والمحتوى. أنماط الأوامر المحظورة توقف المحاولات الواضحة لا الذكية.<br><br><strong>متى توقفه.</strong> إن كان على Pi ما يزعجك فقدانه، أو إن شغّلت <em>الوصول من أي مكان</em>: فذلك يضع لوحة التحكم على رابط عام بلا كلمة مرور، وكل من يملكه سيتحدث مع شيء قادر على تشغيل الأوامر.",
  "set.abilities.workWithHelpers": "العمل مع مساعدين إضافيين",
  "set.abilities.splitBigJobsAcross": "يوزّع المهام الكبيرة على نسخ من نفسه ثم يجمع النتائج.",
  "set.abilities.toggleSubAgents": "تشغيل المساعدين الإضافيين أو إيقافهم",
  "set.abilities.aboutHelpers": "عن المساعدين الإضافيين",
  "set.abilities.forAJobWith": "في مهمة من عدة أجزاء، يستطيع {agent} أن يطلق مساعدين مؤقتين، ويعطي كلًّا منهم جزءًا، ثم يجمع الإجابات. مفيد للبحث أو لأي شيء كثير الخطوات.<br><br><strong>يكلّف أكثر.</strong> كل مساعد إضافي محادثة مستقلة تُحتسب تكلفتها وحدها، لذا قد يكلّف طلب واحد أضعاف الرسالة العادية. الحد مساعدان في الوقت نفسه.",
  "set.abilities.installSkills": "تثبيت المهارات",
  "set.abilities.downloadReadyMadeAbilities": "ينزّل قدرات جاهزة من مكتبة ClawHub.",
  "set.abilities.toggleSkills": "تشغيل المهارات أو إيقافها",
  "set.abilities.aboutSkills": "عن المهارات",
  "set.abilities.skillsAreSmallAdd": "المهارات إضافات صغيرة كتبها أشخاص آخرون، تُنزَّل من clawhub.ai وتعمل على جهازك.<br><br><strong>إنها شيفرة من غرباء.</strong> نحن لا نراجعها. اترك هذا متوقفًا ما لم تكن تريد مهارة بعينها وتثق بمصدرها.",
  "set.abilities.fullDeviceAccess": "وصول كامل إلى الجهاز",
  "set.abilities.offByDefaultLets": "متوقف افتراضيًا. يتيح لـ {agent} تغيير لوحة التحكم هذه نفسها، وإضافة أشياء إليها، والوصول إلى أي مكان في الجهاز، لا إلى مساحة عمله فقط.",
  "set.abilities.toggleFullDeviceAccess": "تشغيل الوصول الكامل أو إيقافه",
  "set.abilities.aboutFullDeviceAccess": "عن الوصول الكامل إلى الجهاز",
  "set.abilities.whyItSOff": "<strong>لماذا هو متوقف.</strong> عادةً يبقى {agent} محصورًا في مساحة عمله: ذاكرته وملاحظاته ولا شيء غيرها. هذا الخيار يزيل الحاجز، تمامًا كتشغيله على حاسوب عادي بلا أي قيود.<br><br><strong>ما الذي تقبله.</strong> يستطيع إعادة كتابة لوحة التحكم هذه وتثبيت البرامج وتغيير أي شيء على الجهاز: تحكّم حقيقي، لكن بلا زر تراجع إن ساء تعديل ما. ويعني أيضًا أنه قد يقرأ ملف إعداداته بصوت عالٍ إن طلب منه ذلك من يتحدث معه بالطريقة المناسبة، وذلك الملف يحتوي مفتاح API الفعّال لديك. اعتبر ذلك بمثابة تسليم هذا المفتاح.<br><br><strong>متى تشغّله.</strong> حين تريده أن يبني الأشياء هنا أو يغيّرها بنفسه، وتقبل أن إصلاح التعديل السيئ مسؤوليتك: الثقة نفسها التي تمنحها لبرنامج تشغّله مباشرة على حاسوبك.",
  "set.abilities.speakUpOnIts": "المبادرة بالحديث",
  "set.abilities.onByDefaultAgent": "يعمل افتراضيًا. قد يراسلك {agent} أولًا بين حين وآخر: تذكير بشيء قلت إنك ستفعله، أو ردّ تنتظره. معظم المراجعات تنتهي بالصمت.",
  "set.abilities.toggleProactiveMessages": "تشغيل الرسائل المبادِرة أو إيقافها",
  "set.abilities.aboutProactiveMessages": "عن الرسائل المبادِرة",
  "set.abilities.whatItDoesEvery": "<strong>ماذا يفعل.</strong> كل نصف ساعة يلقي {agent} نظرة سريعة قليلة التكلفة على ما يعرفه عنك ويقرر إن كان هناك ما يستحق الإرسال فعلًا. إن لم يكن، يبقى صامتًا: لن تصلك رسالة مجدولة من نوع «أطمئن عليك فقط».<br><br><strong>فقط بعد أن تراسله.</strong> لا يبدأ محادثة WhatsApp من تلقاء نفسه أبدًا. وحتى تكتب إليه مرة، لا يوجد مكان يرسل إليه فلا يفعل شيئًا. لا رسائل بين 22:00 و08:00.<br><br><strong>لماذا يعمل.</strong> المساعد الذي يكتفي بالإجابة مجرد مربع بحث. المبادرة بالحديث هي ما يجعلك تشعر بأنه منتبه فعلًا. أوقفه إن كنت تفضّل أن يصمت ما لم تخاطبه.",
  "set.spend.spendingGuard": "حدّ الإنفاق",
  "set.spend.aSafetyCapOn": "سقف أمان لمقدار حديث {agent} مع النموذج المدفوع. بعد تجاوز الحد يتوقف حتى الغد، كي لا تستنزف حلقة خارجة عن السيطرة أو طفل فضولي ميزانيتك.",
  "set.spend.pauseWhenTheLimit": "التوقف عند بلوغ الحد",
