  "crm.build.title": "ابنِ قائمة جهات اتصالك — استوردها من LinkedIn وInstagram",
  "crm.build.intro": "أضف الأشخاص الذين تعرفهم بالفعل. حينها يستطيع مساعدك مراسلة من تسمح لهم، وتذكيرك بمن يجب أن تعود للتواصل معه، وألّا يفقد أي خيط. طريقتان لاستيراد قائمة — اختر إحداهما أو كلتيهما.",
  "crm.build.linkedinTitle": "من LinkedIn",
  "crm.build.li1": "افتح LinkedIn على الحاسوب واذهب إلى <strong>شبكتي ← جهات الاتصال</strong>.",
  "crm.build.li2": "اضغط على <strong>إدارة جهات الاتصال المتزامنة والمستوردة</strong>، ثم ضمن <em>تصدير جهات الاتصال</em> اختر <strong>تصدير جهات الاتصال</strong>.",
  "crm.build.li3": "سيرسل لك LinkedIn ملف CSV بالبريد. نزّله.",
  "crm.build.li4": "اطلب من مساعدك هنا: <em>«أضف هؤلاء الأشخاص إلى جهات اتصالي»</em> وأرفق ملف CSV، أو قل <em>«صدّرت جهات اتصالي من LinkedIn»</em> وسيرشدك خطوة بخطوة.",
  "crm.build.liPrompt": "أريد إضافة جهات اتصالي من LinkedIn. لقد صدّرتها من LinkedIn — ساعدني في استيرادها.",
  "crm.build.instagramTitle": "من Instagram",
  "crm.build.igIntro": "لا يتيح لك Instagram تصدير متابعيك بضغطة واحدة، لكن يمكنك <strong>تنزيل معلوماتك</strong> والقائمة موجودة هناك.",
  "crm.build.ig1": "في تطبيق Instagram: <strong>الملف الشخصي ← القائمة (☰) ← نشاطك ← تنزيل معلوماتك</strong>.",
  "crm.build.ig2": "اختر <strong>المتابعون والمتابَعون</strong> (ألغِ تحديد الباقي ليكون أسرع)، والصيغة <strong>JSON</strong>، ثم <strong>طلب التنزيل</strong>.",
  "crm.build.ig3": "سيرسل لك Instagram رابطًا بالبريد عندما يجهز — غالبًا خلال دقائق، وأحيانًا بضع ساعات. نزّله وفكّ ضغطه.",
  "crm.build.ig4": "اطلب من مساعدك: <em>«أضف الأشخاص الذين أتابعهم على Instagram إلى جهات اتصالي»</em> وأرفق الملف. لاحظ أن Instagram يعطي أسماء مستخدمين لا أرقام هواتف — يمكن للمساعد حفظهم كجهات اتصال وتضيف الأرقام لاحقًا مع تقدّم المحادثات.",
  "crm.build.igPrompt": "نزّلت معلوماتي من Instagram وأريد إضافة الأشخاص الذين أتابعهم إلى جهات اتصالي.",
  "crm.build.linkTitle": "ربط كل شخص بالرقم الصحيح",
  "crm.build.linkIntro": "الاسم نصف الطريق فقط — لمراسلة أحدهم على WhatsApp يحتاج مساعدك إلى رقمه. ثلاث طرق لسدّ هذه الفجوة:",
  "crm.build.link1": "أضف الرقم يدويًا في القائمة أعلاه (مربع <strong>إضافة</strong>). الأسرع للقلّة الأهم من الناس.",
  "crm.build.link2": "اسأل مساعدك: <em>«ما رقم Rosa؟»</em> بعد أن تتحدثا، وسيطابق الاسم مع الرقم الذي رآه.",
  "crm.build.link3": "شغّل <strong>دع مساعدي يقرأ محادثاتي الأخرى على WhatsApp</strong> في القنوات ← WhatsApp. عندما يراسلك شخص جديد، يمكن للمساعد أن يسألك إن كنت تريد إضافته — دون كتابة أي رقم.",
